package org.agentfrc.lesson;
import java.nio.file.*;import java.security.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
public class FuelIntakeTest {
 static Path out;static Properties input=new Properties();static byte[] raw;static double[] max=new double[11];
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 static double d(String k){return Double.parseDouble(input.getProperty(k));}
 @BeforeAll static void hal()throws Exception{out=Path.of(Objects.requireNonNull(System.getenv("FRC_INTAKE_OUTPUT"),"Native-bound runner required"));raw=Files.readAllBytes(out.resolve("input.properties"));input.load(new java.io.ByteArrayInputStream(raw));assertEquals("frc-fuel-intake-input/v1",input.getProperty("schema"));assertEquals(input.getProperty("experimentSha256"),sha(Files.readAllBytes(out.resolve("experiment.json"))));for(String v:List.of("compressed","nominal"))assertEquals(input.getProperty(v+"PropertiesSha256"),sha(Files.readAllBytes(out.resolve(v+"/properties.json"))));edu.wpi.first.hal.HAL.initialize(500,0);}
 @AfterAll static void result()throws Exception{Properties r=new Properties();r.setProperty("inputSha256",sha(raw));for(Class<?> c:List.of(FuelIntakeController.class,FuelIntakePlant.class,FuelIntakeRig.class))r.setProperty(c.getSimpleName()+"ClassSha256",sha(c.getResourceAsStream(c.getSimpleName()+".class").readAllBytes()));String[] labels={"xM","zM","vxMps","vzMps","sphereRadps","rollerRadps","busVolts","batteryAmps","normalLossJ","frictionLossJ","mechanicalResidualJ"};for(int i=0;i<11;i++)r.setProperty("maxDifference."+labels[i],Double.toString(max[i]));r.setProperty("hold","bounded-held-in-nip-only");r.setProperty("release","unsupported-regeneration");r.setProperty("capture","unestablished");r.setProperty("engineeringAcceptance","blocked");try(var stream=Files.newOutputStream(out.resolve("result.properties"),StandardOpenOption.CREATE_NEW)){r.store(stream,"Uncalibrated fixed-support fixture, no accepted capture or release");}}
 static FuelIntakePlant.Config config(){return new FuelIntakePlant.Config(d("massKg"),d("sphereRadiusM"),d("rollerRadiusM"),d("rollerInertiaKgM2"),d("rollerZM"),d("wallXM"),d("gear"),.8);}
 @Test void lawPowerAndSign(){var p=FuelIntakePlant.law(.002,0,-1,.2,0,0,-10,.075,.0381,5000,5,.8);assertEquals(10,p.normal(),1e-12);assertTrue(p.fx()>0);assertTrue(p.rollerTorque()>0);assertTrue(p.frictionLoss()>0);assertEquals(.01,p.potential(),1e-12);var u=FuelIntakePlant.law(.002,0,1,0,1,0,0,.075,0,5000,5,.8);assertEquals(0,u.normal());assertEquals(10,u.normalLoss(),1e-12);}
 @Test void actualIoBoundedHold(){try(var rig=new FuelIntakeRig(config(),1)){int held=0;for(int i=0;i<65;i++){var a=rig.step(true,false,200);assertTrue(Math.abs(a.mechanicalResidual())<1e-5);if(i>=35){assertEquals(FuelIntakeController.Phase.DWELL,rig.controller.phase());assertTrue(Math.abs(a.vx())<.002);assertTrue(a.x()>-.005&&a.x()<.005);assertTrue(a.rollerNormal()>5);held++;}}assertEquals(30,held);}}
 @Test void requestedReverseFailsClosed()throws Exception{try(var rig=new FuelIntakeRig(config(),1)){for(int i=0;i<60;i++)rig.step(true,false,200);var e=assertThrows(IllegalArgumentException.class,()->{for(int i=0;i<100;i++)rig.step(true,true,200);});assertTrue(e.getMessage().contains("Unsupported regeneration"));Files.writeString(out.resolve("unsupported-release.txt"),e.getMessage()+"\n",StandardOpenOption.CREATE_NEW);}}
 @Test void continuousDemandFailsClosed()throws Exception{var p=new FuelIntakePlant(config(),-.06,.075,.15);var e=assertThrows(IllegalArgumentException.class,()->{for(int i=0;i<10000;i++)p.step(-.12,.0001);});assertTrue(e.getMessage().contains("Unsupported regeneration"));Files.writeString(out.resolve("unsupported-continuous.txt"),e.getMessage()+"\n",StandardOpenOption.CREATE_NEW);}
 @Test void sourceScaleFaultStopsController(){try(var rig=new FuelIntakeRig(config(),-1)){for(int i=0;i<5;i++)rig.step(true,false,200);assertEquals(FuelIntakeController.Phase.FAULT,rig.controller.phase());}}
 @Test void nominalTangencyDoesNotCreateRollerForce(){var c=config();var z=new FuelIntakePlant.Config(c.mass(),c.radius(),c.rollerRadius(),c.rollerInertia(),d("nominalRollerZM"),c.wallX(),c.gear(),c.rollerMu());try(var rig=new FuelIntakeRig(z,1)){for(int i=0;i<30;i++){var a=rig.step(true,false,200);assertEquals(0,a.rollerNormal(),1e-12);}}}
 @Test void frictionlessRollerDoesNotEstablishHeldInNip(){var c=config();var f=new FuelIntakePlant.Config(c.mass(),c.radius(),c.rollerRadius(),c.rollerInertia(),c.rollerZ(),c.wallX(),c.gear(),0);try(var rig=new FuelIntakeRig(f,1)){FuelIntakePlant.Sample a=null;for(int i=0;i<65;i++)a=rig.step(true,false,200);assertFalse(Math.abs(a.x())<.005&&Math.abs(a.vx())<.002);}}
 @Test void unsupportedInputsAndExcessOverlapReject(){assertThrows(IllegalArgumentException.class,()->new FuelIntakePlant(config(),0,.05,0));assertThrows(IllegalArgumentException.class,()->FuelIntakePlant.law(.001,Double.NaN,1,0,0,0,0,.075,0,5000,5,.8));assertThrows(IllegalArgumentException.class,()->new FuelIntakePlant(config(),-.06,.075,0).step(0,.001));}
 @Test void alignedRefinement()throws Exception{double[][] coarse=trajectory(200),fine=trajectory(400);for(int i=0;i<coarse.length;i++)for(int j=0;j<11;j++)max[j]=Math.max(max[j],Math.abs(coarse[i][j]-fine[i][j]));double[] tolerance={1e-5,1e-5,1e-4,1e-4,1e-4,1e-4,1e-4,1e-3,1e-5,1e-5,1e-5};for(int j=0;j<11;j++)assertTrue(max[j]<tolerance[j],"Aligned SI component "+j);}
 static double[][] trajectory(int steps)throws Exception{double[][] a=new double[65][11];StringBuilder csv=new StringBuilder("time,xM,zM,vxMps,vzMps,sphereOmega,rollerOmega,busVolts,batteryAmps,normalLossJ,frictionLossJ,mechanicalResidualJ,rollerNormalN,phase\n");try(var rig=new FuelIntakeRig(config(),1)){for(int i=0;i<a.length;i++){var s=rig.step(true,false,steps);a[i]=new double[]{s.x(),s.z(),s.vx(),s.vz(),s.sphereOmega(),s.rollerOmega(),s.bus(),s.current(),s.normalLoss(),s.frictionLoss(),s.mechanicalResidual()};csv.append((i+1)*.02).append(',');for(double v:a[i])csv.append(v).append(',');csv.append(s.rollerNormal()).append(',').append(rig.controller.phase()).append('\n');}}Files.writeString(out.resolve("hold-"+steps+".csv"),csv,StandardOpenOption.CREATE_NEW);return a;}
}
